/* Persistent visual identity. Shared by the room, editor, conversation and traces. */
window.WorkshopIdentity = (() => {
  const palette = [
    {name:'Poppy red',value:'#c94e63'}, {name:'Marigold orange',value:'#de8735'},
    {name:'Sunflower yellow',value:'#d4ac30'}, {name:'Moss green',value:'#569773'},
    {name:'Sky blue',value:'#4e94c5'}, {name:'Twilight indigo',value:'#6c6bb5'},
    {name:'Orchid violet',value:'#a96bb4'}
  ];
  const shapes=[{id:'round',name:'Round companion'},{id:'square',name:'Boxy explorer'},{id:'cat',name:'Cat-eared scout'}];
  const accessories=[{id:'sprout',name:'Sprout'},{id:'antenna',name:'Antenna'},{id:'star',name:'Star'},{id:'none',name:'No accessory'}];
  const symbols=['✿','◆','★','☀','☾','✦','♥'];
  const validColor=value=>/^#[0-9a-f]{6}$/i.test(value||'');
  function ink(color){const hex=validColor(color)?color:'#569773';const rgb=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.179?'#000000':'#ffffff';}
  function defaults(name,index=0){index=Math.max(0,index);const moss=/^moss$/i.test(name),herman=/^herman$/i.test(name);return {color:moss?palette[3].value:herman?palette[1].value:palette[[3,1,4,6,0,2,5][index%7]].value,avatar:moss?'round':herman?'square':shapes[index%3].id,accessory:moss?'sprout':herman?'antenna':accessories[index%4].id,symbol:moss?'✿':herman?'◆':symbols[index%7],provider:'simulation',model:'extractive-v1',memory:'history-only'};}
  function normalize(a,index=0){const d=defaults(a.name,index);return {...d,...a,human:WorkshopHuman.normalize(a),color:validColor(a.color)?a.color:d.color,avatar:shapes.some(s=>s.id===a.avatar)?a.avatar:d.avatar,accessory:accessories.some(s=>s.id===a.accessory)?a.accessory:d.accessory,symbol:symbols.includes(a.symbol)?a.symbol:d.symbol,provider:'simulation',model:'extractive-v1',memory:'history-only'};}
  function style(a){return `--agent:${a.color};--agent-ink:${ink(a.color)}`;}
  function bot(a){const themed=window.WorkshopTheme?.avatar(a);if(themed)return themed;const color=validColor(a.color)?a.color:'#569773';let top='';
    if(a.accessory==='sprout')top='<path d="M45 23V10" stroke="#467957" stroke-width="3"/><path d="M44 14C29 14 28 2 31 3c12-2 16 6 13 11" fill="#71a87d"/><path d="M45 13C45 2 58 1 62 4c-2 9-11 12-17 9" fill="#a4c591"/>';
    if(a.accessory==='antenna')top='<path d="M45 22V10" stroke="#4b5061" stroke-width="3"/><circle cx="45" cy="7" r="5" fill="#f7cf6c" stroke="#685c48" stroke-width="1.5"/>';
    if(a.accessory==='star')top='<path d="m45 2 4 8 9 1-7 6 2 9-8-4-8 4 2-9-7-6 9-1z" fill="#f5cc6b" stroke="#886b3e" stroke-width="1.3"/>';
    const ears=a.avatar==='cat'?`<path d="m18 31-3-20 21 15m20 0 20-15-3 21" fill="${color}" stroke="#48515c" stroke-width="2"/>`:'';
    return `<svg class="bot avatar-${a.avatar}" viewBox="0 0 90 103" aria-hidden="true">${top}${ears}<path d="M30 86v9M60 86v9" stroke="#727b8a" stroke-width="9" stroke-linecap="round"/><rect x="24" y="63" width="43" height="26" rx="${a.avatar==='square'?5:10}" fill="#e2d9c5" stroke="#7e8078" stroke-width="1.4"/><path d="M24 70 13 80M68 70l10 10" stroke="#cbc4b2" stroke-width="8" stroke-linecap="round"/><rect x="17" y="22" width="58" height="45" rx="${a.avatar==='square'?7:17}" fill="${color}" stroke="#48515c" stroke-width="1.7"/><path d="M25 27q20-7 41 0" stroke="white" opacity=".25" fill="none" stroke-width="3"/><rect x="24" y="33" width="44" height="24" rx="${a.avatar==='square'?4:10}" fill="#263d49"/><g class="eyes" fill="#fff4d7"><rect x="33" y="40" width="5" height="7" rx="2.5"/><rect x="54" y="40" width="5" height="7" rx="2.5"/></g><path d="M43 50q3 3 6 0" fill="none" stroke="#fff4d7" stroke-width="1.5"/><circle cx="46" cy="77" r="6" fill="${color}"/><text x="46" y="80" text-anchor="middle" fill="${ink(color)}" font-size="8">${symbols.includes(a.symbol)?a.symbol:'✿'}</text></svg>`;
  }
  function fields(a,esc){let html=`<div class="identity-editor"><div class="avatar-preview" style="${style(a)}">${bot(a)}<span>Appearance preview</span></div><div class="identity-options"><div class="form-pair"><label class="field">Avatar shape<select name="avatar">${shapes.map(s=>`<option value="${s.id}" ${a.avatar===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="field">Accessory<select name="accessory">${accessories.map(s=>`<option value="${s.id}" ${a.accessory===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label></div><label class="field">Identity symbol<select name="symbol">${symbols.map(s=>`<option ${a.symbol===s?'selected':''}>${s}</option>`).join('')}</select></label></div></div><fieldset class="color-field"><legend>Agent color</legend><div class="swatches">${palette.map(c=>`<button type="button" class="swatch ${a.color.toLowerCase()===c.value?'chosen':''}" data-color="${c.value}" style="--swatch:${c.value};--swatch-ink:${ink(c.value)}" aria-label="${c.name}" aria-pressed="${a.color.toLowerCase()===c.value}" title="${c.name}">${a.color.toLowerCase()===c.value?'✓':''}</button>`).join('')}<label class="custom-color">Custom<input name="color" type="color" aria-label="Custom agent color" value="${esc(a.color)}"></label></div><p class="field-help">Color + name + shape + symbol keep every agent recognizable.</p></fieldset>`;if(window.WorkshopTheme?.current==='neon')html=html.replace(/<div class="form-pair">[\s\S]*?<\/div>/,WorkshopHuman.fields(a)).replace('Color + name + shape + symbol','Accent + name + appearance + symbol');return html;}
  function room(agents,selected,statusOf,esc,zoom=1){return `<div class="shared-room" aria-label="Shared illustrated workshop"><div class="room-scroll" tabindex="0" aria-label="Scrollable workshop; all agents have their own workstation"><div class="room-world" style="zoom:${zoom};min-width:${agents.length>2?710:510}px"><div class="studio-wall"><span class="studio-sign">THE SPECTRUM STUDIO <small>Room for every kind of curious.</small></span><svg viewBox="0 0 800 150" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="800" height="150" fill="#e9e1d9"/><path d="M0 148h800" stroke="#b6a997" stroke-width="5"/><rect x="42" y="24" width="125" height="110" rx="40" fill="#8c9da1"/><path d="M49 128V65a55 35 0 0 1 111 0v63z" fill="#bfdbe0"/><circle cx="129" cy="53" r="15" fill="#fff0b3"/><path d="M49 106q25-45 58-10 31-34 53-7v39H49" fill="#98b7a0"/><path d="M49 117q38-25 68-6 28-18 43-3v20H49" fill="#71977e"/><path d="M105 29v99M49 80h111" stroke="#879b9b" stroke-width="5"/><rect x="31" y="130" width="148" height="8" rx="4" fill="#ae997f"/><path d="M601 64h147v8H601M601 121h147v8H601" fill="#ad987b"/><path d="M612 63V34h10v29M628 63V29h9v34M643 63V38h11v25" stroke="#a56c90" stroke-width="7"/><path d="M618 120V91h8v29M633 120V86h10v34M648 120V95h9v25" stroke="#5c8da6" stroke-width="7"/><path d="M663 120V89h9v31" stroke="#c79b50" stroke-width="6"/><rect x="701" y="40" width="21" height="23" rx="3" fill="#c6956f"/><path d="M712 42v-24m0 13q-19-5-10-18 13 2 10 18m0-8q4-19 18-14 0 14-18 14" fill="#69937b"/><rect x="701" y="99" width="27" height="21" rx="3" fill="#b8aa86"/><path d="M714 100q-20-10-12-22 12 1 12 22m0-1q-3-21 14-24 8 18-14 24" fill="#8aa46f"/><path d="M203 18q198 48 384 0" fill="none" stroke="#a5a0a0" stroke-width="2"/>${palette.map((c,i)=>`<path d="m${220+i*52} ${21+Math.sin(i/6*Math.PI)*17} 18 3-11 23z" fill="${c.value}"/>`).join('')}<rect x="233" y="77" width="44" height="54" rx="2" fill="#bb9c7e"/><rect x="237" y="81" width="36" height="46" fill="#f2dfac"/><path d="M245 117q17-34 22-20" stroke="#a96bb4" stroke-width="4" fill="none"/><rect x="526" y="75" width="43" height="55" rx="3" fill="#a39c92"/><rect x="530" y="79" width="35" height="47" fill="#f3e5c6"/><circle cx="548" cy="99" r="10" fill="#de8735"/><path d="M535 119q10-14 25-2" stroke="#569773" stroke-width="4" fill="none"/></svg></div><div class="station-grid" style="--columns:${agents.length>2?3:2}">${agents.map(a=>{const s=statusOf(a.id);const active=['working','using-tool'].includes(s);const label=s==='using-tool'?'Using tool':s==='paused'?'Waiting · paused':s==='cancelled'?'Idle · cancelled':s;return `<button class="station ${s} ${a.id===selected?'selected':''}" data-select-agent="${a.id}" data-agent-name="${esc(a.name)}" style="${style(a)}" aria-pressed="${a.id===selected}" aria-label="Select ${esc(a.name)}, ${label}"><span class="selection-marker">${a.id===selected?'✓ Selected':'Click to select'}</span><span class="station-figure">${bot(a)}${active?'<span class="activity-pips"><i></i><i></i><i></i></span>':''}</span><svg class="desk-art" viewBox="0 0 240 105" aria-hidden="true"><ellipse cx="122" cy="95" rx="100" ry="9" fill="#8e7d791c"/><path d="M38 55v42m162-42v42" stroke="#9d846b" stroke-width="8"/><path d="M20 39h200l10 15H10z" fill="#d0b798"/><path d="M10 54h220v9H10z" fill="#b59a7d"/><path d="M14 59h212" stroke="${a.color}" stroke-width="5"/><rect x="32" y="5" width="49" height="34" rx="3" fill="#455a65"/><rect x="36" y="9" width="41" height="25" rx="2" fill="#d9e2df"/><path d="M41 16h25M41 22h16M41 28h21" stroke="${a.color}" stroke-width="2"/><path d="M57 39v7m-11 0h22" stroke="#5f6b71" stroke-width="3"/><path d="M39 50h41l5 3H35z" fill="#f4ecd9"/><rect x="174" y="25" width="19" height="18" rx="3" fill="${a.color}"/><path d="M193 29q10-1 7 9h-7" stroke="${a.color}" fill="none" stroke-width="3"/><path d="M151 40V13l-11-8" stroke="#777b69" stroke-width="3" fill="none"/><path d="M129 11q-3-14 12-11l9 8z" fill="#e2b566"/><path d="M208 39h15l-2-16h-11z" fill="#ab80a7"/><path d="M215 24v-15m0 10q-13-2-10-12 11 0 10 12m0-5q2-13 12-9 0 10-12 9" fill="#79a07a"/></svg><span class="station-name"><b>${a.symbol}</b> ${esc(a.name)}</span><span class="station-status"><span class="status-dot"></span>${label}</span></button>`;}).join('')}</div><div class="room-bottom">✿ Independent agents, one shared creative space. <span>Explicit simulated handoffs are recorded.</span></div></div></div></div>`;}
  return {palette,shapes,accessories,symbols,ink,defaults,normalize,style,bot,fields,room};
})();
